import { jest } from '@jest/globals';
import OpenAI from 'openai';

describe('OpenAI Mock Test', () => {
  it('should load OpenAI mock from src/__mocks__/openai.js', () => {
    // OpenAI should be mocked via moduleNameMapper in jest.config.js
    console.log('OpenAI constructor:', OpenAI);
    console.log('typeof OpenAI:', typeof OpenAI);
    
    const client = new OpenAI({ apiKey: 'test-key' });
    console.log('client:', client);
    console.log('client constructor:', client.constructor.name);
    
    expect(client).toBeDefined();
    expect(client.chat).toBeDefined();
    expect(client.chat.completions).toBeDefined();
    expect(client.chat.completions.create).toBeDefined();
    expect(typeof client.chat.completions.create).toBe('function');
  });

  it('should return mock responses', async () => {
    const client = new OpenAI({ apiKey: 'test-key' });
    
    const response = await client.chat.completions.create({
      model: 'gpt-4',
      messages: [{ role: 'user', content: 'Hello' }],
    });

    expect(response).toBeDefined();
    expect(response.choices).toBeDefined();
    expect(response.choices[0].message.content).toBe('Mock generated content');
  });
});